STATIC_FILES = {
    'css/app.css': '/* 剧本杀一站式平台 —— 移动端优先，暗色沉浸风 */\n@font-face{\n  font-family:\'TwemojiFallback\';\n  src:url(\'https://cdn.jsdelivr.net/gh/mozilla/twemoji-colr@master/dist/Twemoji.Mozilla.ttf\') format(\'truetype\');\n  unicode-range:U+1F000-1FAFF,U+2600-27BF,U+2B00-2BFF,U+2190-21FF,U+2300-23FF,U+FE00-FE0F,U+1F1E6-1F1FF;\n}\n:root{\n  --bg:#0f0d17; --bg2:#1a1725; --card:#221e30; --card2:#2b2640;\n  --gold:#e8b96a; --gold2:#c99a4a; --rose:#e0668a; --purple:#8a6fd4;\n  --text:#f2eef7; --muted:#a79fb8; --line:#332e45; --ok:#5fd39b;\n}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{background:var(--bg);color:var(--text);\n  font-family:-apple-system,"PingFang SC","Microsoft YaHei","TwemojiFallback",\n  "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif;line-height:1.6}\na{color:inherit;text-decoration:none}\nimg{display:block;max-width:100%}\n.app{max-width:480px;margin:0 auto;min-height:100vh;background:var(--bg);\n  position:relative;padding-bottom:70px}\n\n/* 顶栏 */\n.topbar{position:sticky;top:0;z-index:50;background:rgba(15,13,23,.92);\n  backdrop-filter:blur(10px);padding:14px 16px;display:flex;align-items:center;\n  justify-content:space-between;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:18px;font-weight:700;letter-spacing:1px}\n.topbar .logo{color:var(--gold)}\n.badge{font-size:11px;padding:3px 8px;border-radius:10px;background:var(--card2);color:var(--muted)}\n.badge.on{background:rgba(95,211,155,.15);color:var(--ok)}\n\n/* 通用 */\n.wrap{padding:16px}\n.sec-title{font-size:16px;font-weight:700;margin:18px 16px 10px;display:flex;\n  align-items:center;gap:6px}\n.sec-title .more{margin-left:auto;font-size:12px;color:var(--muted);font-weight:400}\n.card{background:var(--card);border-radius:14px;padding:14px;margin-bottom:12px;\n  border:1px solid var(--line)}\n.row{display:flex;gap:10px}\n.muted{color:var(--muted)}\n.gold{color:var(--gold)}\n.rose{color:var(--rose)}\n.tag{display:inline-block;font-size:11px;padding:2px 8px;border-radius:8px;\n  background:var(--card2);color:var(--gold);margin:2px 4px 2px 0}\n.tag.rose{color:var(--rose);background:rgba(224,102,138,.12)}\n.tag.purple{color:var(--purple);background:rgba(138,111,212,.12)}\n.btn{display:inline-block;background:linear-gradient(135deg,var(--gold),var(--gold2));\n  color:#1a1520;font-weight:700;padding:11px 18px;border-radius:12px;border:none;\n  font-size:14px;cursor:pointer;text-align:center}\n.btn.block{display:block;width:100%}\n.btn.ghost{background:transparent;border:1px solid var(--gold);color:var(--gold)}\n.btn.rose{background:linear-gradient(135deg,var(--rose),#c04d72);color:#fff}\n.btn:disabled{opacity:.4}\n.pill-row{display:flex;gap:8px;overflow-x:auto;padding:4px 16px 8px;scrollbar-width:none}\n.pill-row::-webkit-scrollbar{display:none}\n.pill{white-space:nowrap;padding:7px 14px;border-radius:20px;background:var(--card);\n  font-size:13px;color:var(--muted);border:1px solid var(--line);cursor:pointer}\n.pill.active{background:var(--gold);color:#1a1520;border-color:var(--gold);font-weight:600}\n\n/* 剧本卡 */\n.script-card{display:flex;gap:12px}\n.script-card .cover{width:84px;height:112px;border-radius:10px;object-fit:cover;flex:none;background:var(--card2)}\n.script-card .info{flex:1;min-width:0}\n.script-card .info h3{font-size:16px;margin-bottom:4px}\n.rate{color:var(--gold);font-weight:700}\n.meta{font-size:12px;color:var(--muted);margin:4px 0}\n\n/* 局卡 */\n.session-card .head{display:flex;justify-content:space-between;align-items:flex-start}\n.progress{height:6px;background:var(--card2);border-radius:4px;overflow:hidden;margin:8px 0}\n.progress>i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--rose))}\n.status{font-size:11px;padding:3px 9px;border-radius:8px}\n.status.recruiting{background:rgba(95,211,155,.15);color:var(--ok)}\n.status.full{background:rgba(224,102,138,.15);color:var(--rose)}\n.avatars{display:flex;margin-top:6px}\n.avatars span{width:26px;height:26px;border-radius:50%;background:var(--card2);\n  border:2px solid var(--card);margin-left:-8px;font-size:11px;display:flex;\n  align-items:center;justify-content:center;color:var(--gold)}\n.avatars span:first-child{margin-left:0}\n\n/* 底部导航 */\n.tabbar{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;\n  max-width:480px;background:rgba(26,23,37,.96);backdrop-filter:blur(10px);\n  border-top:1px solid var(--line);display:flex;z-index:60}\n.tabbar a{flex:1;text-align:center;padding:9px 0 12px;font-size:11px;color:var(--muted)}\n.tabbar a.active{color:var(--gold)}\n.tabbar a .ic{font-size:20px;display:block;margin-bottom:2px}\n\n/* 测本 */\n.q-block{margin-bottom:20px}\n.q-block h3{font-size:16px;margin-bottom:12px}\n.opt{padding:13px 15px;border-radius:12px;background:var(--card);border:1px solid var(--line);\n  margin-bottom:10px;cursor:pointer;transition:.15s}\n.opt.sel{border-color:var(--gold);background:rgba(232,185,106,.1)}\n.opt .k{color:var(--gold);font-weight:700;margin-right:8px}\n\n/* 聊天 */\n.chat-list{padding:16px;display:flex;flex-direction:column;gap:12px}\n.msg{max-width:78%;padding:10px 13px;border-radius:14px;font-size:14px;white-space:pre-wrap}\n.msg.me{align-self:flex-end;background:linear-gradient(135deg,var(--gold),var(--gold2));color:#1a1520;border-bottom-right-radius:4px}\n.msg.ai{align-self:flex-start;background:var(--card);border:1px solid var(--line);border-bottom-left-radius:4px}\n.chat-input{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;\n  max-width:480px;background:var(--bg2);padding:10px 12px;display:flex;gap:8px;border-top:1px solid var(--line)}\n.chat-input input{flex:1;background:var(--card);border:1px solid var(--line);border-radius:20px;\n  padding:10px 15px;color:var(--text);font-size:14px;outline:none}\n\n/* 表单 */\n.field{margin-bottom:14px}\n.field label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}\n.field input,.field select,.field textarea{width:100%;background:var(--card);\n  border:1px solid var(--line);border-radius:10px;padding:11px 13px;color:var(--text);\n  font-size:14px;outline:none}\n.field input:focus,.field select:focus{border-color:var(--gold)}\n\n/* 数据看板 */\n.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.stat{background:var(--card);border-radius:14px;padding:16px;border:1px solid var(--line)}\n.stat .num{font-size:26px;font-weight:800;color:var(--gold)}\n.stat .lbl{font-size:12px;color:var(--muted);margin-top:2px}\n\n/* 入口卡(首页) */\n.entry{background:var(--card);border-radius:16px;padding:20px;margin-bottom:14px;\n  border:1px solid var(--line);display:flex;align-items:center;gap:16px;cursor:pointer}\n.entry .em{font-size:34px}\n.entry h3{font-size:17px}\n.entry p{font-size:12px;color:var(--muted)}\n.entry .arrow{margin-left:auto;color:var(--gold);font-size:20px}\n\n.hero{padding:26px 20px;background:linear-gradient(160deg,#2a2140,#171326);\n  border-radius:0 0 24px 24px;margin-bottom:8px}\n.hero h2{font-size:22px;line-height:1.35}\n.hero p{color:var(--muted);font-size:13px;margin-top:8px}\n.empty{text-align:center;color:var(--muted);padding:40px 20px;font-size:13px}\n.loading{text-align:center;color:var(--muted);padding:30px}\n.divider{height:1px;background:var(--line);margin:14px 0}\n.fab{position:fixed;bottom:84px;left:50%;transform:translateX(calc(-50% + 150px));\n  width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,var(--gold),var(--gold2));\n  color:#1a1520;font-size:26px;display:flex;align-items:center;justify-content:center;\n  box-shadow:0 6px 20px rgba(232,185,106,.4);z-index:55;cursor:pointer}\n\n/* 搜索栏 */\n.search-bar{display:flex;gap:8px}\n.search-bar input{flex:1;background:var(--card);border:1px solid var(--line);border-radius:12px;\n  padding:11px 14px;color:var(--text);font-size:14px;outline:none}\n.search-bar input:focus{border-color:var(--gold)}\n\n/* 筛选栏 */\n.filter-bar{display:flex;gap:8px;padding:0 0 12px;flex-wrap:wrap}\n.filter-bar select,.filter-bar input{flex:1;min-width:80px;background:var(--card);\n  border:1px solid var(--line);border-radius:10px;padding:9px 10px;color:var(--text);\n  font-size:13px;outline:none}\n.filter-bar select:focus,.filter-bar input:focus{border-color:var(--gold)}\n\n/* ============ 桌面端 / Web 适配 (>=768px) ============ */\n/* 目标：宽屏下不再是"手机窄条"，而是真正的网页版——更宽的容器、\n   多列卡片网格、更大气的留白与字号。 */\n@media (min-width:768px){\n  body{background:var(--bg);display:block}\n  /* 容器整体放宽到 1120px，居中，两侧描边 */\n  .app{max-width:1120px;width:100%;margin:0 auto;\n    border-left:1px solid var(--line);border-right:1px solid var(--line);\n    padding-bottom:90px}\n  .topbar{position:sticky;left:auto;transform:none;width:100%;max-width:1120px;\n    margin:0 auto;padding:16px 40px}\n  .topbar h1{font-size:23px}\n\n  .wrap{max-width:1120px;margin:0 auto;padding:24px 40px}\n  .hero{padding:52px 40px;border-radius:0 0 36px 36px}\n  .hero h2{font-size:32px}\n  .hero p{font-size:16px}\n  .sec-title{font-size:19px;margin:28px 40px 16px}\n\n  /* 【核心】列表区域做成多列网格：把 .wrap 里连续的卡片自动排成 2 列。\n     用 grid 包裹——通过给 .wrap 内的卡片网格化实现。 */\n  .grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}\n  .grid-2 .card{margin-bottom:0}\n\n  /* 剧本卡 / 拼局卡 / 通用卡：桌面下自动两列（利用 columns 兜底，\n     但主用 JS 加的 .grid-2 容器；这里对散落卡片也给个更宽舒展的观感） */\n  .script-card .cover{width:104px;height:140px}\n  .script-card .info h3{font-size:18px}\n  .meta{font-size:13px}\n  .session-card .head h3{font-size:18px!important}\n\n  /* 搜索/筛选栏 */\n  .search-bar input{font-size:16px;padding:14px 18px}\n  .search-bar .btn{padding:14px 28px;font-size:15px}\n  .filter-bar{gap:12px}\n  .filter-bar select,.filter-bar input{font-size:14px;padding:11px 14px;min-width:140px;flex:0 1 auto}\n\n  /* 底部导航桌面居中，加宽 */\n  .tabbar{max-width:1120px;left:50%;transform:translateX(-50%)}\n  .tabbar a{font-size:13px;padding:14px 0}\n  .tabbar a .ic{font-size:22px}\n\n  /* 聊天 */\n  .chat-input{max-width:1120px;padding:14px 40px}\n  .msg{max-width:52%;font-size:15px}\n  .chat-list{padding:24px 40px;max-width:1120px;margin:0 auto}\n\n  /* 入口卡（首页身份选择）——三列并排 */\n  .entry{padding:26px 30px;margin-bottom:16px}\n  .entry .em{font-size:42px}\n  .entry h3{font-size:20px}\n  .entry p{font-size:13px}\n\n  /* 数据看板 */\n  .stat-grid{grid-template-columns:repeat(4,1fr);gap:18px}\n  .stat .num{font-size:32px}\n  .stat .lbl{font-size:13px}\n\n  .field input,.field select,.field textarea{padding:12px 16px;font-size:15px}\n  .field{max-width:560px}\n  .q-block h3{font-size:19px}\n  .opt{padding:16px 20px;font-size:15px}\n  .tag{font-size:12px;padding:3px 10px}\n  .fab{bottom:104px;transform:translateX(calc(-50% + 520px))}\n}\n\n/* 更大屏幕：卡片可 3 列 */\n@media (min-width:1080px){\n  .grid-2{grid-template-columns:repeat(2,1fr)}\n}\n',
    'js/common.js': "// 共享工具\nconst API = {\n  get: (u) => fetch(u).then(r => r.json()),\n  post: (u, body) => fetch(u, {\n    method: 'POST', headers: {'Content-Type': 'application/json'},\n    body: JSON.stringify(body || {})\n  }).then(r => r.json()),\n};\nfunction stars(n){ n=Math.round(n||0); return '★'.repeat(n)+'☆'.repeat(5-n); }\nfunction esc(s){ return (s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\nfunction initAiBadge(){\n  fetch('/api/system/info').then(r=>r.json()).then(d=>{\n    const b=document.getElementById('ai-badge'); if(!b)return;\n    if(d.llm_ready){b.textContent='AI · '+d.model;b.className='badge on';}\n    else{b.textContent='AI 降级模式';}\n  });\n}\n",
    'js/player.js': '// 玩家端 —— 拼车广场筛选 + 千岛测本 + 角色陪伴\nconst app = document.getElementById(\'view\');\nlet curScripts = [];\nlet plazaFilter = { city: \'\', date: \'\', seat: \'\' };\nlet seatTypes = [\'全部\',\'普通位\',\'补贴位\',\'CP位\',\'恋陪\',\'陪伴位\'];\n\nconst views = { home:renderHome, test:renderTest, plaza:renderPlaza, find:renderFind, roles:renderRoles, mine:renderMine };\nfunction go(name){\n  document.querySelectorAll(\'.tabbar a\').forEach(a=>a.classList.toggle(\'active\', a.dataset.v===name));\n  (views[name]||renderHome)();\n  window.scrollTo(0,0);\n}\n\n// ---------- 首页 ----------\nasync function renderHome(){\n  app.innerHTML = `<div class="hero"><h2>今天，想玩点什么本？</h2>\n    <p>拼车 · 测本测角色 · 角色陪伴，一站搞定</p></div>\n    <div class="wrap">\n      <div class="card" style="display:flex;align-items:center;gap:12px;cursor:pointer;margin-bottom:16px" onclick="go(\'test\')">\n        <div style="font-size:28px">🔮</div>\n        <div style="flex:1"><b>搜本测角色</b><div class="muted" style="font-size:12px">搜你想玩的本，测测适合演谁</div></div>\n        <div class="gold" style="font-size:20px">›</div>\n      </div>\n      <div class="sec-title">🔥 热门拼车 <span class="more" onclick="go(\'plaza\')">全部 ›</span></div>\n      <div id="home-sessions" class="loading grid-2">加载中…</div>\n      <div class="sec-title">📊 2025 高分好本 <span class="more" onclick="go(\'find\')">全部 ›</span></div>\n      <div id="home-scripts" class="loading grid-2">加载中…</div>\n    </div>`;\n  const ss = await API.get(\'/api/player/sessions\');\n  const hs=document.getElementById(\'home-sessions\'); hs.className=\'grid-2\';\n  hs.innerHTML = ss.slice(0,4).map(sessionCard).join(\'\')||\'<div class="empty">暂无拼车局</div>\';\n  const sc = await API.get(\'/api/player/scripts\');\n  curScripts = sc;\n  // 高分排序\n  sc.sort((a,b)=>b.rating-a.rating);\n  const hsc=document.getElementById(\'home-scripts\'); hsc.className=\'grid-2\';\n  hsc.innerHTML = sc.slice(0,6).map(scriptCard).join(\'\');\n}\n\nfunction searchAndTest(kw){\n  if(!kw.trim()){alert(\'请输入剧本名称\');return;}\n  const found = curScripts.filter(s=>s.title.includes(kw.trim()));\n  if(found.length===0){alert(\'未找到匹配的剧本，试试搜索其他关键词\');return;}\n  if(found.length===1){openRoleTest(found[0]);return;}\n  // 多个匹配：展示选择列表\n  app.innerHTML = `<div class="wrap"><div class="sec-title">🔍 搜索「${esc(kw)}」</div>\n    <p class="muted" style="margin:0 0 14px">找到 ${found.length} 个匹配剧本，点击进入测角色</p>\n    ${found.map(s=>`<div class="card script-card" onclick="openRoleTest(curScripts.find(x=>x.id===${s.id}))">\n      <img class="cover" src="${s.cover}" onerror="this.style.opacity=.3">\n      <div class="info"><h3>${esc(s.title)} <span class="rate">★${s.rating}</span></h3>\n      <div class="meta">${s.category} · ${s.player_min}-${s.player_max}人</div>\n      <div>${(s.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n      <button class="btn ghost" style="margin-top:6px;padding:5px 12px;font-size:12px">测适合角色 ›</button></div></div>`).join(\'\')}</div>`;\n}\n\n// ---------- 千岛模式：测角色 ----------\nlet roleQuiz=[], roleAnswers={}, roleData=null;\nasync function openRoleTest(script){\n  roleData = script;\n  roleQuiz = []; roleAnswers = {};\n  const r = await API.get(\'/api/player/scripts/\'+script.id+\'/role-quiz\');\n  roleQuiz = r.questions || [];\n  roleData.roles = r.roles || [];\n  app.innerHTML = `<div class="wrap">\n    <div class="sec-title">🎭 测适合角色</div>\n    <div class="card" style="text-align:center;padding:18px">\n      <h3>${esc(r.script_title)}</h3>\n      <div class="meta">${script.category} · ${script.player_min}-${script.player_max}人 · ★${script.rating}</div>\n      <div style="margin-top:8px">${(script.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n      <p class="muted" style="font-size:13px;margin-top:8px">${(r.roles||[]).map(r=>r.name).join(\' · \')}</p>\n    </div>\n    <div id="role-quiz"></div>\n    <button class="btn block" id="submit-role" onclick="submitRoleTest()" disabled>完成测试 · 匹配我的角色</button>\n  </div>`;\n  renderRoleQuiz();\n}\nfunction renderRoleQuiz(){\n  const box=document.getElementById(\'role-quiz\');\n  if(!box)return;\n  box.innerHTML = roleQuiz.map(q=>`<div class="q-block"><h3>${esc(q.title)}</h3>\n    ${q.options.map(o=>`<div class="opt" data-q="${q.id}" data-k="${o.key}"\n       onclick="pickRole(\'${q.id}\',\'${o.key}\',this)"><span class="k">${o.key}</span>${esc(o.text)}</div>`).join(\'\')}\n    </div>`).join(\'\');\n}\nfunction pickRole(qid,k,el){\n  roleAnswers[qid]=k;\n  el.parentElement.querySelectorAll(\'.opt\').forEach(o=>o.classList.remove(\'sel\'));\n  el.classList.add(\'sel\');\n  const btn=document.getElementById(\'submit-role\');\n  if(btn) btn.disabled = Object.keys(roleAnswers).length<roleQuiz.length;\n}\nasync function submitRoleTest(){\n  const btn=document.getElementById(\'submit-role\'); btn.textContent=\'AI 匹配中…\'; btn.disabled=true;\n  const r = await API.post(\'/api/player/scripts/\'+roleData.id+\'/test-role\',{answers:roleAnswers});\n  app.innerHTML = `<div class="wrap">\n    <div class="card" style="background:linear-gradient(160deg,#2a2140,#1a1526);text-align:center;padding:24px">\n      <div class="muted" style="font-size:13px">《${esc(r.script_title)}》· 你的角色</div>\n      <h2 class="gold" style="margin:8px 0">${esc(r.primary)}</h2>\n      <p style="font-size:14px">${esc(r.primary_reason)}</p>\n      <div class="divider"></div>\n      <div style="font-size:13px;color:var(--muted)">次推荐：<b>${esc(r.secondary||\'\')}</b> — ${esc(r.secondary_reason||\'\')}</div>\n      <div class="divider"></div>\n      <p style="font-size:13px">${esc(r.analysis||\'\')}</p>\n      <div class="tag purple" style="margin-top:8px">💡 ${esc(r.play_tip||\'\')}</div>\n    </div>\n    <button class="btn block" style="margin-top:12px" onclick="go(\'plaza\')">去拼这个本 ›</button>\n    <button class="btn block ghost" style="margin-top:8px" onclick="renderHome()">搜其他本</button>\n  </div>`;\n}\n\n// ---------- 拼车广场（城市+日期+补位类型筛选）----------\nasync function renderPlaza(){\n  app.innerHTML = `<div class="wrap">\n    <div class="sec-title">🚗 拼车广场</div>\n    <div class="filter-bar">\n      <select id="f-city" onchange="applyPlazaFilter()"><option value="">全部城市</option><option value="成都">成都</option><option value="北京">北京</option></select>\n      <input id="f-date" type="date" onchange="applyPlazaFilter()" placeholder="选择日期">\n      <select id="f-seat" onchange="applyPlazaFilter()">${seatTypes.map(t=>`<option value="${t===\'全部\'?\'\':t}">${t}</option>`).join(\'\')}</select>\n    </div>\n    <div id="plaza-list" class="loading">加载中…</div>\n  </div>`;\n  await loadPlaza();\n}\nasync function applyPlazaFilter(){\n  plazaFilter.city = document.getElementById(\'f-city\')?.value||\'\';\n  plazaFilter.date = document.getElementById(\'f-date\')?.value||\'\';\n  plazaFilter.seat = document.getElementById(\'f-seat\')?.value||\'\';\n  loadPlaza();\n}\nasync function loadPlaza(){\n  const box = document.getElementById(\'plaza-list\'); if(!box)return;\n  box.innerHTML=\'<div class="loading">加载中…</div>\';\n  let ss = await API.get(\'/api/player/sessions\');\n  // 前端筛选\n  if(plazaFilter.city) ss = ss.filter(s=>s.city===plazaFilter.city);\n  if(plazaFilter.date) ss = ss.filter(s=>s.start_time&&s.start_time.startsWith(plazaFilter.date));\n  if(plazaFilter.seat) ss = ss.filter(s=>s.seat_type===plazaFilter.seat);\n  box.className=\'grid-2\';\n  box.innerHTML = ss.map(sessionCard).join(\'\')||\'<div class="empty" style="grid-column:1/-1">暂无匹配的拼车局<br><span style="font-size:12px">试试放宽筛选条件</span></div>\';\n}\n\n// ---------- 卡片模板 ----------\nfunction scriptCard(s){\n  return `<div class="card script-card" onclick="openRoleTest(curScripts.find(x=>x.id===${s.id}))">\n    <img class="cover" src="${s.cover}" onerror="this.style.opacity=.3">\n    <div class="info"><h3>${esc(s.title)} <span class="rate">★${s.rating}</span></h3>\n      <div class="meta">${s.category} · ${s.player_min}-${s.player_max}人 · ${Math.round(s.duration/60)}h · 难度${\'●\'.repeat(s.difficulty)}</div>\n      <div>${(s.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n      <button class="btn ghost" style="margin-top:6px;padding:5px 12px;font-size:12px">测适合角色 ›</button>\n    </div></div>`;\n}\nfunction sessionCard(s){\n  const pct = Math.round(s.joined_players/s.need_players*100);\n  const av = (s.members||[]).map(m=>`<span>${esc((m.nickname||\'?\')[0])}</span>`).join(\'\');\n  const seatColor = s.seat_type===\'CP位\'?\'rose\':s.seat_type===\'恋陪\'?\'purple\':s.seat_type===\'补贴位\'?\'tag\':s.seat_type===\'陪伴位\'?\'purple\':\'\';\n  return `<div class="card session-card" onclick="sessionDetail(${s.id})">\n    <div class="head">\n      <div><h3 style="font-size:16px">${esc(s.script_title)}\n        <span class="tag ${seatColor}" style="font-size:10px">${esc(s.seat_type||\'普通位\')}</span></h3>\n        <div class="meta">${esc(s.shop_name)} · ${s.start_time} · ${esc(s.city||\'\')}</div></div>\n      <span class="status ${s.status}">${s.status===\'full\'?\'已满\':\'招募中\'}</span>\n    </div>\n    <div class="progress"><i style="width:${pct}%"></i></div>\n    <div class="row" style="justify-content:space-between;align-items:center">\n      <div class="avatars">${av}<span style="color:var(--muted)">${s.joined_players}/${s.need_players}</span></div>\n      <div><span class="gold" style="font-weight:700">¥${s.price}</span> <span class="muted" style="font-size:12px">DM ${esc(s.dm_name)}</span></div>\n    </div>\n    <div class="meta" style="margin-top:6px">💬 ${esc(s.note||\'\')}</div>\n  </div>`;\n}\n\n// ---------- 测本 Tab：搜本测角色（主入口）----------\nlet qList=[], answers={};\nasync function renderTest(){\n  // 确保剧本库已加载（供搜索匹配）\n  if(!curScripts.length){ curScripts = await API.get(\'/api/player/scripts\'); }\n  app.innerHTML = `<div class="wrap">\n    <div class="sec-title">🔮 测本 · 搜本测角色</div>\n    <p class="muted" style="margin:0 0 14px">搜索你想玩的本，测测你适合演哪个角色</p>\n    <div class="search-bar" style="margin-bottom:16px">\n      <input id="test-search" placeholder="搜索剧本名称，如「流氓叙事」…" onkeydown="if(event.key===\'Enter\')searchAndTest(document.getElementById(\'test-search\').value)">\n      <button class="btn" onclick="searchAndTest(document.getElementById(\'test-search\').value)">搜本测角色</button>\n    </div>\n    <div class="sec-title" style="margin-left:0">🔥 热门本，点开直接测</div>\n    <div id="test-hot" class="loading">加载中…</div>\n    <div class="divider"></div>\n    <p class="muted" style="font-size:12px">不确定玩什么？也可以用 <a class="gold" onclick="renderQuizEntry()" style="cursor:pointer">大问卷推本 ›</a></p>\n    </div>`;\n  // 热门本快捷入口（按评分排序取前 6）\n  const sc = [...curScripts].sort((a,b)=>b.rating-a.rating).slice(0,6);\n  document.getElementById(\'test-hot\').innerHTML = sc.map(scriptCard).join(\'\') || \'<div class="empty">暂无剧本</div>\';\n}\n\n// 大问卷推本（改为二级入口）\nasync function renderQuizEntry(){\n  app.innerHTML = `<div class="wrap">\n    <div class="sec-title">🔮 大问卷推本</div>\n    <p class="muted" style="margin:0 0 16px">答几道题，AI 给你推荐适合的本。</p>\n    <div id="quiz"></div>\n    <button class="btn block ghost" style="margin-top:12px" onclick="renderTest()">← 返回搜本测角色</button></div>`;\n  qList = await API.get(\'/api/player/test/questionnaire\');\n  answers={};\n  renderQuiz();\n}\nfunction renderQuiz(){\n  const box=document.getElementById(\'quiz\'); if(!box)return;\n  box.innerHTML = qList.map(q=>`<div class="q-block"><h3>${esc(q.title)}</h3>\n    ${q.options.map(o=>`<div class="opt" data-q="${q.id}" data-k="${o.key}" onclick="pick(\'${q.id}\',\'${o.key}\',this)"><span class="k">${o.key}</span>${esc(o.text)}</div>`).join(\'\')}</div>`).join(\'\')+\n    `<button class="btn block" id="submit-test" onclick="submitTest()" disabled>完成测试 · 生成推荐</button>`;\n}\nfunction pick(qid,k,el){answers[qid]=k;el.parentElement.querySelectorAll(\'.opt\').forEach(o=>o.classList.remove(\'sel\'));el.classList.add(\'sel\');document.getElementById(\'submit-test\').disabled=Object.keys(answers).length<qList.length;}\nasync function submitTest(){\n  const btn=document.getElementById(\'submit-test\'); btn.textContent=\'AI 分析中…\'; btn.disabled=true;\n  const r=await API.post(\'/api/player/test/submit\',{answers});\n  app.innerHTML=`<div class="wrap">\n    <div class="card" style="background:linear-gradient(160deg,#2a2140,#1a1526);text-align:center;padding:24px">\n      <div class="muted" style="font-size:13px">你的玩家人设</div>\n      <h2 class="gold" style="margin:8px 0">${esc(r.persona_title)}</h2>\n      <div>${(r.tags||[]).map(t=>`<span class="tag purple">${esc(t)}</span>`).join(\'\')}</div>\n      <p style="margin-top:12px;font-size:14px">${esc(r.analysis)}</p></div>\n    <div class="sec-title">为你推荐</div>\n    ${(r.recommend_scripts||[]).map(rec=>`<div class="card script-card" onclick="openRoleTest(curScripts.find(x=>x.id===${rec.id}))">\n      <img class="cover" src="${rec.cover||\'\'}" onerror="this.style.opacity=.3">\n      <div class="info"><h3>${esc(rec.title)} <span class="rate">★${rec.rating||\'\'}</span></h3>\n      <p class="muted" style="font-size:13px">${esc(rec.reason)}</p>\n      <button class="btn ghost" style="margin-top:8px;padding:6px 14px;font-size:13px">进入测角色 ›</button></div></div>`).join(\'\')}\n    <button class="btn block ghost" onclick="renderTest()">重新测一次</button></div>`;\n}\n\n// ---------- 找店找本（高分好本用真实数据）----------\nasync function renderFind(){\n  app.innerHTML = `<div class="wrap"><div class="sec-title">🔍 找本 · 找店 · 找 DM</div></div>\n    <div class="pill-row" id="cats"></div>\n    <div class="pill-row">\n      <span class="pill active" onclick="findTab(\'script\',this)">剧本</span>\n      <span class="pill" onclick="findTab(\'shop\',this)">门店</span>\n      <span class="pill" onclick="findTab(\'dm\',this)">DM</span>\n    </div>\n    <div id="find-list" class="wrap loading">加载中…</div>`;\n  const cats=[\'全部\',\'推理\',\'情感\',\'机制\',\'欢乐\',\'恐怖\'];\n  document.getElementById(\'cats\').innerHTML = cats.map((c,i)=>`<span class="pill ${i===0?\'active\':\'\'}" onclick="filterCat(\'${c}\',this)">${c}</span>`).join(\'\');\n  findTab(\'script\');\n}\nlet findMode=\'script\', findCat=\'全部\';\nfunction filterCat(c,el){findCat=c;el.parentElement.querySelectorAll(\'.pill\').forEach(p=>p.classList.remove(\'active\'));el.classList.add(\'active\');loadFind();}\nfunction findTab(m,el){findMode=m;if(el){el.parentElement.querySelectorAll(\'.pill\').forEach(p=>p.classList.remove(\'active\'));el.classList.add(\'active\');}loadFind();}\nasync function loadFind(){\n  const box=document.getElementById(\'find-list\'); box.className=\'wrap\'; box.innerHTML=\'<div class="loading">加载中…</div>\';\n  if(findMode===\'script\'){\n    box.className=\'wrap grid-2\';\n    const q = findCat===\'全部\'?\'\':\'?category=\'+encodeURIComponent(findCat);\n    const sc = await API.get(\'/api/player/scripts\'+q);\n    sc.sort((a,b)=>b.rating-a.rating);\n    box.innerHTML = sc.map(s=>`<div class="card script-card" onclick="openRoleTest(s)">\n      <img class="cover" src="${s.cover}" onerror="this.style.opacity=.3">\n      <div class="info"><h3>${esc(s.title)} <span class="rate">★${s.rating}</span> <span class="muted" style="font-size:11px">${s.play_count}人玩过</span></h3>\n      <div class="meta">${s.category} · ${s.player_min}-${s.player_max}人 · ${Math.round(s.duration/60)}h</div>\n      <div>${(s.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n      <p class="muted" style="font-size:12px;margin-top:4px">${esc(s.intro||\'\').substring(0,60)}…</p>\n      <button class="btn ghost" style="margin-top:4px;padding:4px 10px;font-size:11px">测适合角色 ›</button></div></div>`).join(\'\');\n  }else if(findMode===\'shop\'){\n    box.className=\'wrap grid-2\';\n    const sh=await API.get(\'/api/player/shops\');\n    box.innerHTML=sh.map(s=>`<div class="card" onclick="shopDetail(${s.id})">\n      <div class="row"><img class="cover" style="width:70px;height:70px;border-radius:10px;object-fit:cover" src="${s.cover}" onerror="this.style.opacity=.3">\n      <div><h3 style="font-size:16px">${esc(s.name)} <span class="rate">★${s.rating}</span></h3>\n      <div class="meta">${esc(s.city)} · ${s.room_count}间房</div>\n      <p class="muted" style="font-size:12px">${esc(s.intro)}</p></div></div></div>`).join(\'\');\n  }else{\n    box.className=\'wrap grid-2\';\n    const dms=await API.get(\'/api/player/dms\');\n    box.innerHTML=dms.map(d=>`<div class="card"><div class="row" style="align-items:center">\n      <div style="width:48px;height:48px;border-radius:50%;background:var(--card2);display:flex;align-items:center;justify-content:center;font-size:22px">🎙️</div>\n      <div style="flex:1"><h3 style="font-size:15px">${esc(d.nickname)} <span class="rate" style="font-size:12px">★${d.rating}</span></h3>\n      <div class="meta">${esc(d.shop_name)} · ${d.fans}粉丝</div>\n      <div>${(d.good_at||\'\').split(\',\').map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div></div></div>\n      <p class="muted" style="font-size:12px;margin-top:6px">${esc(d.intro)}</p></div>`).join(\'\');\n  }\n}\n\n// ---------- 角色陪伴 ----------\nasync function renderRoles(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">💬 角色陪伴</div>\n    <p class="muted" style="margin:0 0 14px">意犹未尽？和剧本里的角色继续聊聊</p>\n    <div id="role-list" class="loading">加载中…</div></div>`;\n  const rs=await API.get(\'/api/player/roles\');\n  const rl=document.getElementById(\'role-list\'); rl.className=\'grid-2\';\n  rl.innerHTML=rs.map(r=>`<div class="card" onclick="openChat(\'${esc(r.name)}\',\'${esc(r.script)}\')">\n    <div class="row" style="align-items:center">\n    <div style="width:54px;height:54px;border-radius:14px;background:linear-gradient(135deg,var(--purple),var(--rose));display:flex;align-items:center;justify-content:center;font-size:26px">🎭</div>\n    <div style="flex:1"><h3 style="font-size:16px">${esc(r.name)}</h3><div class="meta">${esc(r.script)}</div>\n    <p class="muted" style="font-size:12px">${esc(r.tagline)}</p></div>\n    <div class="gold" style="font-size:20px">›</div></div></div>`).join(\'\');\n}\nlet chatHistory=[], chatRole=\'\';\nfunction openChat(name,script){\n  chatRole=name; chatHistory=[];\n  document.querySelector(\'.tabbar\').style.display=\'none\';\n  app.innerHTML=`<div class="topbar" style="position:sticky"><h1 style="font-size:16px">🎭 ${esc(name)} <span class="muted" style="font-size:12px;font-weight:400">${esc(script)}</span></h1>\n    <span class="badge" onclick="closeChat()" style="cursor:pointer">返回</span></div>\n    <div class="chat-list" id="chat" style="padding-bottom:80px">\n      <div class="msg ai">（${esc(name)}正静静看着你……说点什么吧）</div></div>\n    <div class="chat-input"><input id="chat-in" placeholder="对 ${esc(name)} 说…" onkeydown="if(event.key===\'Enter\')sendChat()">\n      <button class="btn" onclick="sendChat()">发送</button></div>`;\n}\nfunction closeChat(){document.querySelector(\'.tabbar\').style.display=\'flex\';go(\'roles\');}\nasync function sendChat(){\n  const inp=document.getElementById(\'chat-in\'); const msg=inp.value.trim(); if(!msg)return;\n  const box=document.getElementById(\'chat\'); box.innerHTML+=`<div class="msg me">${esc(msg)}</div>`; inp.value=\'\'; box.scrollTop=box.scrollHeight;\n  chatHistory.push({role:\'user\',content:msg});\n  const tip=document.createElement(\'div\'); tip.className=\'msg ai\'; tip.textContent=\'…\'; box.appendChild(tip); box.scrollTop=box.scrollHeight;\n  const r=await API.post(\'/api/player/roles/chat\',{role_name:chatRole,message:msg,history:chatHistory});\n  tip.textContent=r.reply||\'（信号中断）\'; chatHistory.push({role:\'assistant\',content:r.reply||\'\'}); box.scrollTop=box.scrollHeight;\n}\n\nfunction renderMine(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">👤 我的</div>\n    <div class="card" style="text-align:center;padding:24px">\n    <div style="width:64px;height:64px;border-radius:50%;background:var(--card2);margin:0 auto 10px;display:flex;align-items:center;justify-content:center;font-size:30px">🕵️</div>\n    <h3>情感玩家Nana</h3><div class="muted" style="font-size:13px">成都 · 情感/沉浸/爱BE</div></div>\n    <div class="card"><b>我的局</b><p class="muted" style="font-size:13px;margin-top:6px">· 《流氓叙事》CP位（明天18:00）<br>· 《如故》（已满员）</p></div>\n    <div class="card"><b>测本记录</b><p class="muted" style="font-size:13px;margin-top:6px">《流氓叙事》→ 推荐角色：程走柳</p></div>\n    <button class="btn block ghost" onclick="location.href=\'/\'">切换身份</button></div>`;\n}\n\nasync function scriptDetail(id){const s=await API.get(\'/api/player/scripts/\'+id);openRoleTest(s);}\nasync function sessionDetail(id){\n  const s=await API.get(\'/api/player/sessions/\'+id);\n  const ok=s.status===\'recruiting\';\n  if(confirm(`《${s.script_title}》\\n${s.shop_name} · ${s.start_time} · ${s.city}\\nDM ${s.dm_name} · ¥${s.price} · ${s.seat_type}\\n${s.joined_players}/${s.need_players}\\n${s.note}\\n\\n${ok?\'点确定上车拼局\':\'该局已满员\'}`)){\n    if(ok){const r=await API.post(\'/api/player/sessions/\'+id+\'/join\',{user_id:5});if(r.error)alert(r.error);else{alert(\'上车成功！\');go(\'plaza\');}}\n  }\n}\nasync function shopDetail(id){\n  const s=await API.get(\'/api/player/shops/\'+id);\n  alert(`${s.name}\\n${s.address}\\n评分 ★${s.rating}\\n\\n${s.intro}\\n\\nDM：${(s.dms||[]).map(d=>d.nickname).join(\'、\')}`);\n}\n\ninitAiBadge(); go(\'home\');\n',
    'js/merchant.js': '// 店家端逻辑（默认店铺 id=1, owner id=1）\nconst app=document.getElementById(\'view\');\nconst SHOP_ID=1;\nconst views={dash:renderDash,schedule:renderSchedule,scripts:renderScripts,dms:renderDMs};\nfunction go(name){document.querySelectorAll(\'.tabbar a\').forEach(a=>a.classList.toggle(\'active\',a.dataset.v===name));(views[name]||renderDash)();window.scrollTo(0,0);}\n\nasync function renderDash(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">📊 经营看板</div><div id="dash" class="loading">加载中…</div></div>`;\n  const d=await API.get(`/api/merchant/shops/${SHOP_ID}/dashboard`);\n  document.getElementById(\'dash\').innerHTML=`\n    <div class="stat-grid">\n      <div class="stat"><div class="num">${d.total_sessions}</div><div class="lbl">总场次</div></div>\n      <div class="stat"><div class="num">${d.fill_rate}%</div><div class="lbl">满场率</div></div>\n      <div class="stat"><div class="num">${d.total_players}</div><div class="lbl">累计玩家</div></div>\n      <div class="stat"><div class="num">¥${d.revenue}</div><div class="lbl">预估流水</div></div>\n    </div>\n    <div class="sec-title">🔥 热门剧本</div>\n    ${(d.hot_scripts||[]).map(h=>`<div class="card row" style="justify-content:space-between"><b>${esc(h.title)}</b><span class="gold">${h.count}场</span></div>`).join(\'\')||\'<div class="empty">暂无数据</div>\'}`;\n}\n\nasync function renderSchedule(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">📅 排期管理 <span class="more" onclick="openNew()">＋ 开场</span></div><div id="sch" class="loading">加载中…</div></div>`;\n  const list=await API.get(`/api/merchant/shops/${SHOP_ID}/schedule`);\n  document.getElementById(\'sch\').innerHTML=list.map(s=>`\n    <div class="card">\n      <div class="row" style="justify-content:space-between"><b>${esc(s.script_title)}</b>\n        <span class="status ${s.status}">${statusText(s.status)}</span></div>\n      <div class="meta">🕐 ${s.start_time} · DM ${esc(s.dm_name)} · ¥${s.price}</div>\n      <div class="progress"><i style="width:${Math.round(s.joined_players/s.need_players*100)}%"></i></div>\n      <div class="row" style="justify-content:space-between;align-items:center">\n        <span class="muted" style="font-size:13px">${s.joined_players}/${s.need_players} 人</span>\n        <div>\n          <button class="btn ghost" style="padding:5px 12px;font-size:12px" onclick="setStatus(${s.id},\'confirmed\')">确认成团</button>\n          <button class="btn ghost" style="padding:5px 12px;font-size:12px" onclick="setStatus(${s.id},\'cancelled\')">取消</button>\n        </div>\n      </div>\n    </div>`).join(\'\')||\'<div class="empty">暂无排期，点右上角开场</div>\';\n}\nfunction statusText(s){return {recruiting:\'招募中\',full:\'已满\',confirmed:\'已成团\',finished:\'已结束\',cancelled:\'已取消\'}[s]||s;}\nasync function setStatus(id,st){await API.post(`/api/merchant/schedule/${id}/status`,{status:st});renderSchedule();}\n\nasync function openNew(){\n  const scripts=await API.get(\'/api/player/scripts\');\n  const dms=await API.get(`/api/merchant/shops/${SHOP_ID}/dms`);\n  app.innerHTML=`<div class="wrap"><div class="sec-title">＋ 新开场次</div>\n    <div class="field"><label>剧本</label><select id="f-script">${scripts.map(s=>`<option value="${s.id}" data-p="${s.player_max}">${esc(s.title)}</option>`).join(\'\')}</select></div>\n    <div class="field"><label>DM</label><select id="f-dm"><option value="">未派单</option>${dms.map(d=>`<option value="${d.id}">${esc(d.nickname)}</option>`).join(\'\')}</select></div>\n    <div class="field"><label>开场时间</label><input id="f-time" type="datetime-local"></div>\n    <div class="field"><label>人数</label><input id="f-need" type="number" value="6"></div>\n    <div class="field"><label>价格</label><input id="f-price" type="number" value="198"></div>\n    <button class="btn block" onclick="submitNew()">发布场次</button>\n    <button class="btn block ghost" style="margin-top:8px" onclick="renderSchedule()">取消</button></div>`;\n}\nasync function submitNew(){\n  const t=document.getElementById(\'f-time\').value;\n  if(!t){alert(\'请选择开场时间\');return;}\n  const time=t.replace(\'T\',\' \');\n  const r=await API.post(\'/api/merchant/schedule\',{\n    shop_id:SHOP_ID, script_id:+document.getElementById(\'f-script\').value,\n    dm_id:document.getElementById(\'f-dm\').value?+document.getElementById(\'f-dm\').value:null,\n    start_time:time, need_players:+document.getElementById(\'f-need\').value,\n    price:+document.getElementById(\'f-price\').value});\n  if(r.error)alert(r.error);else{alert(\'场次已发布，玩家可在拼车广场看到并上车\');renderSchedule();}\n}\n\nasync function renderScripts(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">📚 剧本库</div><div id="sl" class="loading">加载中…</div></div>`;\n  const list=await API.get(\'/api/player/scripts\');\n  document.getElementById(\'sl\').innerHTML=list.map(s=>`<div class="card script-card">\n    <img class="cover" src="${s.cover}" onerror="this.style.opacity=.3">\n    <div class="info"><h3>${esc(s.title)} <span class="rate" style="font-size:13px">★${s.rating}</span></h3>\n    <div class="meta">${s.category} · ${s.player_min}-${s.player_max}人 · 玩过${s.play_count}次</div>\n    <div>${(s.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div></div></div>`).join(\'\');\n}\n\nasync function renderDMs(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">🎙️ DM 花名册</div><div id="dl" class="loading">加载中…</div></div>`;\n  const list=await API.get(`/api/merchant/shops/${SHOP_ID}/dms`);\n  document.getElementById(\'dl\').innerHTML=list.map(d=>`<div class="card">\n    <div class="row" style="align-items:center"><div style="width:44px;height:44px;border-radius:50%;background:var(--card2);display:flex;align-items:center;justify-content:center;font-size:20px">🎙️</div>\n    <div style="flex:1"><h3 style="font-size:15px">${esc(d.nickname)} <span class="rate" style="font-size:12px">★${d.rating}</span></h3>\n    <div class="meta">擅长：${esc(d.good_at)} · ${d.fans}粉丝</div></div>\n    <span class="status ${d.available?\'recruiting\':\'full\'}">${d.available?\'可接单\':\'休息中\'}</span></div></div>`).join(\'\');\n}\n\ninitAiBadge(); go(\'dash\');\n',
    'js/dm.js': '// DM 端逻辑（默认 DM 用户 id=2）\nconst app=document.getElementById(\'view\');\nconst UID=2;\nconst views={orders:renderOrders,market:renderMarket,profile:renderProfile};\nfunction go(name){document.querySelectorAll(\'.tabbar a\').forEach(a=>a.classList.toggle(\'active\',a.dataset.v===name));(views[name]||renderOrders)();window.scrollTo(0,0);}\n\nasync function renderOrders(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">🎬 我的场次</div><div id="ol" class="loading">加载中…</div></div>`;\n  const list=await API.get(\'/api/dm/orders/\'+UID);\n  document.getElementById(\'ol\').innerHTML=list.map(s=>`<div class="card">\n    <div class="row" style="justify-content:space-between"><b>${esc(s.script_title)}</b>\n      <span class="status ${s.status}">${statusText(s.status)}</span></div>\n    <div class="meta">🏪 ${esc(s.shop_name)} · 🕐 ${s.start_time}</div>\n    <div class="meta">${s.joined_players}/${s.need_players} 人 · ¥${s.price}</div></div>`).join(\'\')||\'<div class="empty">暂无带本场次</div>\';\n}\nfunction statusText(s){return {recruiting:\'招募中\',full:\'已满\',confirmed:\'已成团\',finished:\'已结束\',cancelled:\'已取消\'}[s]||s;}\n\nasync function renderMarket(){\n  app.innerHTML=`<div class="wrap"><div class="sec-title">📢 接单市场</div>\n    <p class="muted" style="margin:0 0 14px">这些场次还没派 DM，抢单接活</p><div id="ml" class="loading">加载中…</div></div>`;\n  const list=await API.get(\'/api/dm/market\');\n  document.getElementById(\'ml\').innerHTML=list.map(s=>`<div class="card">\n    <div class="row" style="justify-content:space-between"><b>${esc(s.script_title)}</b><span class="tag">${esc(s.script_category)}</span></div>\n    <div class="meta">🏪 ${esc(s.shop_name)} · 🕐 ${s.start_time} · ¥${s.price}</div>\n    <button class="btn block" style="margin-top:8px" onclick="take(${s.id})">抢单接本</button></div>`).join(\'\')||\'<div class="empty">暂无可接场次（都已派单）</div>\';\n}\nasync function take(id){\n  const r=await API.post(\'/api/dm/market/\'+id+\'/take\',{user_id:UID});\n  if(r.error)alert(r.error);else{alert(\'接单成功！已加入我的场次\');go(\'orders\');}\n}\n\nasync function renderProfile(){\n  const d=await API.get(\'/api/dm/profile/\'+UID);\n  app.innerHTML=`<div class="wrap"><div class="sec-title">👤 我的主页</div>\n    <div class="card" style="text-align:center;padding:24px">\n    <div style="width:64px;height:64px;border-radius:16px;background:linear-gradient(135deg,var(--purple),var(--rose));margin:0 auto 10px;display:flex;align-items:center;justify-content:center;font-size:30px">🎙️</div>\n    <h3>${esc(d.nickname)} <span class="rate" style="font-size:14px">★${d.rating}</span></h3>\n    <div class="muted" style="font-size:13px">${esc(d.shop_name)} · ${d.fans} 粉丝</div>\n    <div style="margin-top:10px">${(d.good_at||\'\').split(\',\').map(t=>`<span class="tag">${esc(t)}</span>`).join(\'\')}</div>\n    <div style="margin-top:6px">${(d.style||\'\').split(\',\').map(t=>`<span class="tag purple">${esc(t)}</span>`).join(\'\')}</div>\n    <p style="margin-top:12px;font-size:14px">${esc(d.intro)}</p></div>\n    <div class="card row" style="justify-content:space-between;align-items:center">\n      <div><b>接单状态</b><div class="muted" style="font-size:12px">开启后玩家可在市场找到你</div></div>\n      <button class="btn ${d.available?\'\':\'ghost\'}" id="av-btn" onclick="toggleAv(${d.available})">${d.available?\'接单中\':\'已休息\'}</button>\n    </div></div>`;\n}\nasync function toggleAv(cur){\n  const r=await API.post(\'/api/dm/profile/\'+UID+\'/available\',{available:!cur});\n  renderProfile();\n}\n\ninitAiBadge(); go(\'orders\');\n',
}
